import path from 'path'
import raw from './data/pokemon.json'
import { normalize } from './match'

/**
 * The Gen 1 + 2 answer set, generated by scripts/whos-that-pokemon/ from PokeAPI.
 * Server-only: it holds every answer, so only route handlers may import it. Clients get
 * one silhouette image per round (via /api/wtp/round-image) and nothing that names the
 * Pokémon until they guess.
 */
export interface WtpPokemon {
  id: number
  slug: string
  name: string
  gen: 1 | 2
  types: string[]
  genus: string
  flavor: { text: string; game: string }
  heightM: number
  weightKg: number
  color: string | null
  habitat: string | null
  shape: string | null
  legendary: boolean
  evolution: { stage: number; from: string | null; evolvesFurther: boolean }
  hasCry: boolean
  assets: { s: string; r: string; c: string }
}

export const POKEMON = raw as WtpPokemon[]

const byId = new Map(POKEMON.map((p) => [p.id, p]))

/** Every Pokémon's name as `normalize` sees it, for telling a near-miss from another answer. */
export const NORMALIZED_NAMES: ReadonlySet<string> = new Set(POKEMON.map((p) => normalize(p.name)))

export function getPokemon(id: number): WtpPokemon | undefined {
  return byId.get(id)
}

const ASSET_ROOT = '/assets/wtp'

/**
 * Where the silhouette file sits on disk. Kept out of public/ and never handed to the
 * client as a URL: a stable URL per answer would let a script build a silhouette-to-name
 * table from a few runs. /api/wtp/round-image streams it instead, re-encoded per request.
 */
export function silhouetteFile(p: WtpPokemon): string {
  return path.join(process.cwd(), 'src', 'lib', 'wtp', 'data', 'silhouettes', `${p.assets.s}.webp`)
}

export function revealUrl(p: WtpPokemon): string {
  return `${ASSET_ROOT}/r/${p.assets.r}.webp`
}

export function cryUrl(p: WtpPokemon): string | null {
  return p.hasCry ? `${ASSET_ROOT}/c/${p.assets.c}.mp3` : null
}
